  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #0f1117;
  --surface: #1a1d27;
  --surface-2: #22263a;
  --border: #2e3348;
  --border-hover: #4a5080;
  --accent: #6c63ff;
  --accent-light: #8b85ff;
  --accent-glow: rgba(108, 99, 255, 0.25);
  --text: #e8eaf0;
  --text-muted: #8b91a8;
  --text-dim: #5c6278;
  --success: #34d399;
  --success-bg: rgba(52, 211, 153, 0.1);
  --error: #f87171;
  --error-bg: rgba(248, 113, 113, 0.1);
  --check-size: 20px;
}

body {
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  background-color: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 16px 80px;
  line-height: 1.6;
}

.quiz-wrapper {
  width: 100%;
  max-width: 680px;
}

/* Header */
.quiz-header {
  margin-bottom: 40px;
  text-align: center;
}

.quiz-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--accent-glow);
  border: 1px solid rgba(108, 99, 255, 0.4);
  color: var(--accent-light);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 5px 12px;
  border-radius: 100px;
  margin-bottom: 20px;
}

.quiz-badge svg {
  width: 13px;
  height: 13px;
}

.quiz-header h1 {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.5px;
  line-height: 1.2;
  margin-bottom: 10px;
  background: linear-gradient(135deg, #e8eaf0 0%, #a8aacc 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.quiz-header p {
  color: var(--text-muted);
  font-size: 15px;
}

/* Progress bar */
.progress-bar-track {
  width: 100%;
  height: 3px;
  background: var(--surface-2);
  border-radius: 99px;
  margin-bottom: 36px;
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--accent-light));
  border-radius: 99px;
  transition: width 0.4s ease;
  width: 0%;
}

/* Form fields */
.form-field {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 28px;
  margin-bottom: 20px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.form-field:hover {
  border-color: var(--border-hover);
}

.form-field.answered {
  border-color: rgba(108, 99, 255, 0.4);
  box-shadow: 0 0 0 1px rgba(108, 99, 255, 0.1);
}

.question-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}

.question-number {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent-light);
  background: var(--accent-glow);
  border: 1px solid rgba(108, 99, 255, 0.3);
  padding: 3px 10px;
  border-radius: 100px;
}

.multi-badge {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-dim);
  padding: 3px 8px;
  border: 1px solid var(--border);
  border-radius: 100px;
}

.question-text {
  font-size: 17px;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 8px;
  line-height: 1.4;
}

.help-text {
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 20px;
  display: flex;
  align-items: flex-start;
  gap: 7px;
  background: rgba(139, 133, 255, 0.06);
  border: 1px solid rgba(139, 133, 255, 0.15);
  border-radius: 8px;
  padding: 10px 12px;
  line-height: 1.5;
}

.help-text svg {
  flex-shrink: 0;
  width: 15px;
  height: 15px;
  color: var(--accent-light);
  margin-top: 1px;
}

/* Options */
.options-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  list-style: none;
}

.option-label {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
}

.option-label:hover {
  border-color: var(--border-hover);
  background: #282d42;
}

.option-label.selected {
  border-color: var(--accent);
  background: rgba(108, 99, 255, 0.12);
}

.option-label.selected .option-text {
  color: #c5c2ff;
}

/* Custom checkbox */
.custom-checkbox {
  position: relative;
  flex-shrink: 0;
}

.custom-checkbox input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.checkmark {
  width: var(--check-size);
  height: var(--check-size);
  border: 2px solid var(--border-hover);
  border-radius: 6px;
  background: var(--surface);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
  flex-shrink: 0;
}

.option-label.selected .checkmark {
  background: var(--accent);
  border-color: var(--accent);
}

.checkmark svg {
  width: 12px;
  height: 12px;
  stroke: white;
  stroke-width: 2.5;
  opacity: 0;
  transform: scale(0.6);
  transition: all 0.15s ease;
}

.option-label.selected .checkmark svg {
  opacity: 1;
  transform: scale(1);
}

.option-text {
  font-size: 15px;
  color: var(--text);
  transition: color 0.15s ease;
  line-height: 1.4;
}

/* Submit section */
.submit-section {
  margin-top: 32px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}

.submit-btn {
  width: 100%;
  padding: 16px 32px;
  background: linear-gradient(135deg, var(--accent) 0%, #8b5cf6 100%);
  color: white;
  font-size: 16px;
  font-weight: 600;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
  letter-spacing: 0.01em;
  position: relative;
  overflow: hidden;
  box-shadow: 0 4px 24px rgba(108, 99, 255, 0.35);
}

.submit-btn::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(255,255,255,0.08), transparent);
}

.submit-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 32px rgba(108, 99, 255, 0.5);
}

.submit-btn:active {
  transform: translateY(0);
  box-shadow: 0 2px 12px rgba(108, 99, 255, 0.3);
}

.submit-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
  box-shadow: 0 4px 12px rgba(108, 99, 255, 0.15);
}

.submit-hint {
  font-size: 13px;
  color: var(--text-dim);
}

/* Result card */
.result-card {
  display: none;
  margin-top: 28px;
  padding: 28px;
  border-radius: 16px;
  border: 1px solid;
  text-align: center;
  animation: fadeIn 0.35s ease;
}

.result-card.show {
  display: block;
}

.result-card.good {
  background: var(--success-bg);
  border-color: rgba(52, 211, 153, 0.3);
}

.result-card.bad {
  background: var(--error-bg);
  border-color: rgba(248, 113, 113, 0.3);
}

.result-score {
  font-size: 44px;
  font-weight: 800;
  margin-bottom: 6px;
  letter-spacing: -1px;
}

.result-card.good .result-score { color: var(--success); }
.result-card.bad .result-score { color: var(--error); }

.result-label {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 6px;
}

.result-card.good .result-label { color: var(--success); }
.result-card.bad .result-label { color: var(--error); }

.result-desc {
  font-size: 14px;
  color: var(--text-muted);
}

/* Feedback states */
.form-field.correct {
  border-color: rgba(52, 211, 153, 0.5);
  box-shadow: 0 0 0 1px rgba(52, 211, 153, 0.1);
}

.form-field.incorrect {
  border-color: rgba(248, 113, 113, 0.4);
  box-shadow: 0 0 0 1px rgba(248, 113, 113, 0.08);
}

.option-label.correct-answer {
  border-color: rgba(52, 211, 153, 0.6) !important;
  background: rgba(52, 211, 153, 0.08) !important;
}

.option-label.wrong-pick {
  border-color: rgba(248, 113, 113, 0.5) !important;
  background: rgba(248, 113, 113, 0.08) !important;
}

.feedback-tag {
  margin-top: 14px;
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 100px;
  display: inline-block;
}

.feedback-tag.correct { color: var(--success); background: rgba(52, 211, 153, 0.12); border: 1px solid rgba(52,211,153,0.3); }
.feedback-tag.incorrect { color: var(--error); background: rgba(248,113,113,0.12); border: 1px solid rgba(248,113,113,0.3); }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

@media (max-width: 520px) {
