const QUESTIONS = [
  {
    id: "q1",
    number: "Question 1",
    text: "Which of the following are statically typed programming languages?",
    helpText: "Static typing means variable types are checked at compile time, before the program runs.",
    options: [
      { id: "q1a", label: "TypeScript" },
      { id: "q1b", label: "Python" },
      { id: "q1c", label: "Rust" },
      { id: "q1d", label: "Java" },
    ],
    correctIds: ["q1a", "q1c", "q1d"],
  },
  {
    id: "q2",
    number: "Question 2",
    text: "Which languages were primarily designed for systems programming?",
    options: [
      { id: "q2a", label: "Ruby" },
      { id: "q2b", label: "C" },
      { id: "q2c", label: "Rust" },
      { id: "q2d", label: "C++" },
    ],
    correctIds: ["q2b", "q2c", "q2d"],
  },
  {
    id: "q3",
    number: "Question 3",
    text: "Which of the following languages support first-class functions?",
    options: [
      { id: "q3a", label: "JavaScript" },
      { id: "q3b", label: "Haskell" },
      { id: "q3c", label: "Python" },
      { id: "q3d", label: "COBOL" },
    ],
    correctIds: ["q3a", "q3b", "q3c"],
  },
];

// ─── State ────────────────────────────────────────────────────────────────────
const state = {
  selections: {
    q1: new Set(),
    q2: new Set(),
    q3: new Set(),
  },
  submitted: false,
};

// ─── Render helpers ───────────────────────────────────────────────────────────
function renderCheckIcon() {
  return `<svg viewBox="0 0 12 12" fill="none" xmlns="http://www.w3.org/2000/svg">
    <polyline points="2,6 5,9 10,3" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
}

function renderInfoIcon() {
  return `<svg viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg" style="color:var(--accent-light)">
    <circle cx="8" cy="8" r="6.5" stroke="currentColor" stroke-width="1.5"/>
    <path d="M8 7v5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
    <circle cx="8" cy="4.5" r="0.75" fill="currentColor"/>
  </svg>`;
}

function renderStarIcon() {
  return `<svg viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M8 1l1.8 3.6L14 5.3l-3 2.9.7 4.1L8 10.4l-3.7 1.9.7-4.1-3-2.9 4.2-.7z"
      stroke="currentColor" stroke-width="1.4" stroke-linejoin="round" fill="currentColor"/>
  </svg>`;
}

function renderQuestion(q) {
  const helpHtml = q.helpText
    ? `<p class="help-text">${renderInfoIcon()}<span>${q.helpText}</span></p>`
    : "";

  const optionsHtml = q.options
    .map((opt) => {
      const checked = state.selections[q.id].has(opt.id);
      return `
      <li>
        <label class="option-label${checked ? " selected" : ""}" data-question="${q.id}" data-option="${opt.id}">
          <span class="custom-checkbox">
            <input type="checkbox" ${checked ? "checked" : ""} aria-label="${opt.label}" tabindex="0">
            <span class="checkmark">${renderCheckIcon()}</span>
          </span>
          <span class="option-text">${opt.label}</span>
        </label>
      </li>`;
    })
    .join("");

  const answered = state.selections[q.id].size > 0;

  return `
  <div class="form-field${answered ? " answered" : ""}" id="${q.id}">
    <div class="question-meta">
      <span class="question-number">${q.number}</span>
      <span class="multi-badge">Select all that apply</span>
    </div>
    <p class="question-text">${q.text}</p>
    ${helpHtml}
    <ul class="options-list" role="group" aria-label="${q.text}">
      ${optionsHtml}
    </ul>
  </div>`;
}

function renderQuiz() {
  return QUESTIONS.map(renderQuestion).join("");
}

// ─── Progress ─────────────────────────────────────────────────────────────────
function updateProgress() {
  const answered = QUESTIONS.filter((q) => state.selections[q.id].size > 0).length;
  const pct = (answered / QUESTIONS.length) * 100;
  document.querySelector(".progress-bar-fill").style.width = pct + "%";

  const allAnswered = answered === QUESTIONS.length;
  document.getElementById("submit-btn").disabled = !allAnswered;
  document.querySelector(".submit-hint").textContent = allAnswered
    ? "All questions answered — ready to submit!"
    : `${QUESTIONS.length - answered} question${QUESTIONS.length - answered !== 1 ? "s" : ""} remaining`;
}

// ─── Toggle selection ─────────────────────────────────────────────────────────
function toggleOption(questionId, optionId) {
  if (state.submitted) return;
  const sel = state.selections[questionId];
  sel.has(optionId) ? sel.delete(optionId) : sel.add(optionId);

  const label = document.querySelector(
    `[data-question="${questionId}"][data-option="${optionId}"]`
  );
  if (label) {
    label.classList.toggle("selected", sel.has(optionId));
    const cb = label.querySelector('input[type="checkbox"]');
    if (cb) cb.checked = sel.has(optionId);
  }

  // Update answered state on form-field
  const field = document.getElementById(questionId);
  if (field) field.classList.toggle("answered", sel.size > 0);

  updateProgress();
}

// ─── Submit ───────────────────────────────────────────────────────────────────
function gradeQuiz() {
  let correct = 0;

  QUESTIONS.forEach((q) => {
    const userSet = state.selections[q.id];
    const correctSet = new Set(q.correctIds);

    const isCorrect =
      userSet.size === correctSet.size &&
      [...userSet].every((id) => correctSet.has(id));

    if (isCorrect) correct++;

    const field = document.getElementById(q.id);
    field.classList.remove("answered");
    field.classList.add(isCorrect ? "correct" : "incorrect");

    // Mark each option
    q.options.forEach((opt) => {
      const label = document.querySelector(
        `[data-question="${q.id}"][data-option="${opt.id}"]`
      );
      if (!label) return;
      const isCorrectAnswer = correctSet.has(opt.id);
      const wasSelected = userSet.has(opt.id);

      if (isCorrectAnswer) label.classList.add("correct-answer");
      else if (wasSelected) label.classList.add("wrong-pick");
    });

    // Feedback tag
    const tag = document.createElement("div");
    tag.className = `feedback-tag ${isCorrect ? "correct" : "incorrect"}`;
    tag.textContent = isCorrect ? "✓ Correct" : "✗ Incorrect";
    const existing = field.querySelector(".feedback-tag");
    if (existing) existing.remove();
    field.appendChild(tag);
  });

  // Result card
  const pct = Math.round((correct / QUESTIONS.length) * 100);
  const good = correct >= 2;
  const card = document.getElementById("result-card");
  card.className = `result-card show ${good ? "good" : "bad"}`;
  card.innerHTML = `
    <div class="result-score">${correct}/${QUESTIONS.length}</div>
    <div class="result-label">${good ? "Well done!" : "Keep studying!"}</div>
    <div class="result-desc">${pct}% correct · ${
    correct === QUESTIONS.length
      ? "Perfect score! You're a language expert."
      : correct === 0
      ? "No worries — brush up on your language history and try again."
      : "Good effort! Review the highlighted answers above."
  }</div>`;

  card.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

// ─── Mount ────────────────────────────────────────────────────────────────────
function mount() {
  const container = document.getElementById("quiz-container");
  container.innerHTML = renderQuiz();

  // Delegate click events on option labels
  container.addEventListener("click", (e) => {
    const label = e.target.closest(".option-label");
    if (!label || state.submitted) return;
    e.preventDefault();
    toggleOption(label.dataset.question, label.dataset.option);
  });

  // Keyboard support
  container.addEventListener("keydown", (e) => {
    if (e.key !== " " && e.key !== "Enter") return;
    const label = e.target.closest(".option-label");
    if (!label || state.submitted) return;
    e.preventDefault();
    toggleOption(label.dataset.question, label.dataset.option);
  });

  // Make labels focusable
  container.querySelectorAll(".option-label").forEach((label) => {
    label.setAttribute("tabindex", "0");
    label.setAttribute("role", "checkbox");
  });

  document.getElementById("submit-btn").addEventListener("click", () => {
    if (state.submitted) return;
    state.submitted = true;
    document.getElementById("submit-btn").disabled = true;
    document.getElementById("submit-btn").textContent = "Submitted ✓";
    document.querySelector(".submit-hint").textContent = "";
    gradeQuiz();
  });

  updateProgress();
}

document.addEventListener("DOMContentLoaded", mount);
