+      { id: "q1b", label: "Python" },
+      { id: "q1c", label: "Rust" },
+      { id: "q1d", label: "Java" },
+    ],
+    correctIds: ["q1a", "q1c", "q1d"],
+  },
+  {
+    id: "q2",
+    number: "Question 2",
+    text: "Which languages were primarily designed for systems programming?",
+    options: [
+      { id: "q2a", label: "Ruby" },
+      { id: "q2b", label: "C" },
+      { id: "q2c", label: "Rust" },
+      { id: "q2d", label: "C++" },
+    ],
+    correctIds: ["q2b", "q2c", "q2d"],
+  },
+  {
+    id: "q3",
+    number: "Question 3",
+    text: "Which of the following languages support first-class functions?",
+    options: [
+      { id: "q3a", label: "JavaScript" },
+      { id: "q3b", label: "Haskell" },
+      { id: "q3c", label: "Python" },
+      { id: "q3d", label: "COBOL" },
+    ],
+    correctIds: ["q3a", "q3b", "q3c"],
+  },
