// ─── Toggle selection ─────────────────────────────────────────────────────────
function toggleOption(questionId, optionId) {
  if (state.submitted) return;
  const sel = state.selections[questionId];
  sel.has(optionId) ? sel.delete(optionId) : sel.add(optionId);

  const label = document.querySelector(
    `[data-question="${questionId}"][data-option="${optionId}"]`
  );
  if (label) {
    label.classList.toggle("selected", sel.has(optionId));
    const cb = label.querySelector('input[type="checkbox"]');
    if (cb) cb.checked = sel.has(optionId);
  }

  // Update answered state on form-field
  const field = document.getElementById(questionId);
  if (field) field.classList.toggle("answered", sel.size > 0);

  updateProgress();
